codeExample.code:
#include <stdio.h>

int main() {
    int age;
    float marks;
    char grade;

    // Taking input from user
    printf("Enter your age: ");
    scanf("%d", &age);

    printf("Enter your marks: ");
    scanf("%f", &marks);

    printf("Enter your grade (A/B/C): ");
    scanf(" %c", &grade);

    // Displaying output
    printf("\n--- Student Report ---\n");
    printf("Age   : %d years\n", age);
    printf("Marks : %.2f\n", marks);
    printf("Grade : %c\n", grade);

    return 0;
}

